const getRepoFile = async (query) => {
  try {
    const octokit2 = getInstance();
    const { owner, repo, path, branch } = query;
    const response = await octokit2.repos.getContent({
      owner,
      repo,
      path,
      ref: branch
    });
    return atob(response.data.content);
  } catch (error) {
    const err = error;
    console.error(err);
    throw new Error(err.message);
  }
};
const getIssues = createAsyncThunk("github/getIssues", async (url) => {
  try {
    const repoURL = new RepoAPIURL(url);
    const queryIssues = `
        query ($owner: String!, $repo: String!) {
          repository(owner: $owner, name: $repo) {
            issues(first: 20) {
              nodes {
                number
              }
            }
          }
        }
      `;
    const headers = getHeaders();
    const issuesGQL = await graphql2(queryIssues, {
      owner: repoURL.owner,
      repo: repoURL.repo,
      headers
    });
    let issueNums = issuesGQL.repository.issues.nodes.map((issue) => issue.number);
    const queryIssue = `query($owner: String!, $repo: String!, $issueNumber: Int!) {
        repository(owner: $owner, name: $repo) {
          issue(number: $issueNumber) {
            id
            createdAt
            updatedAt
            title
            body
            number
            state
            issueType {
              id
              name
              description
            }
            milestone {
              id
              title
            }
            labels(first: 10) {
              nodes {
                name
                color
              }
            }
            repository {
              nameWithOwner
            }
            trackedIssues(first: 20) {
              nodes {
                id
                number
                title
                state
                repository {
                  nameWithOwner
                }
              }
            }
            trackedInIssues(first: 10) {
              nodes {
                id
                number
                title
                state
              }
            }
          }
        }
      }`;
    const issueDetailPromises = issueNums.map((issueNumber) => {
      const issue = graphql2(queryIssue, {
        owner: repoURL.owner,
        repo: repoURL.repo,
        issueNumber,
        headers
      });
      return issue;
    });
    const issueDetailsResponses = await Promise.all(issueDetailPromises);
    const issueArray = issueDetailsResponses.map((github) => {
      return github.repository.issue;
    });
    const issues = new Issues();
    issues.fromGitHubGraphQL(issueArray);
    return issues.toIssuesObject();
  } catch (error) {
    const err = error;
    console.error(err);
    throw new Error(err.message);
  }
});
